#define FRINGE_BOD(direction, family, edge_a, edge_b) \
    (g_game->root_bod_catalog.fringe_catalog \
            .entries[family][direction][edge_a][edge_b].object)

int debug_report_stub(char* format, ...);
extern char g_used_fringe_bods_format[]; // "Used %i fringe bods\n"

static inline void emit_track_fringe(cRSubLoc* cell, Fringe** slot_pointer, int direction, int family, int& edge_a, int edge_b)
{
    Fringe*& slot = *slot_pointer;
    Fringe* fringe = g_game->subgame.fringe_manager.GetFringe();
    slot = fringe;
    fringe->SetObject(FRINGE_BOD(direction, family, edge_a, edge_b));
    slot->list_flags |= BOD_FLAG_RENDER_ENABLED;
    slot->position = cell->position;
    tColour color;
    tColour* skirt_color = g_game->subgame.GetSkirtColour(&color);
    slot->color = *skirt_color;
    edge_a = 0;
}

void cRSubGame::FringeEdgeTrack()
{
    g_game->subgame.fringe_manager.Init();

    int edge_a = 0;
    int row = 0;
    if (runtime_row_count > 0) {
        SubRow* row_record = runtime_rows;
        cRSubLoc* cell = &runtime_cells[0][0];
        SubRow* row_record_head = row_record;

        do {
            int lane_count =
                sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0]);
            do {
                unsigned char open_edge_mask = cell->open_edge_mask;
                int family = 0;
                if (open_edge_mask
                    == (SUBLOC_OPEN_PREVIOUS_LANE | SUBLOC_OPEN_PREVIOUS_ROW)) {
                    family = 1;
                } else if (open_edge_mask
                    == (SUBLOC_OPEN_NEXT_LANE | SUBLOC_OPEN_PREVIOUS_ROW)) {
                    family = 3;
                } else if (open_edge_mask
                    == (SUBLOC_OPEN_PREVIOUS_LANE | SUBLOC_OPEN_NEXT_ROW)) {
                    family = 2;
                } else if (open_edge_mask
                    == (SUBLOC_OPEN_NEXT_LANE | SUBLOC_OPEN_NEXT_ROW)) {
                    family = 4;
                }

                unsigned char tile_id = cell->tile_id;
                if (tile_id == SUBLOC_TILE_RAMP_LEFT_BRACE
                    || tile_id == SUBLOC_TILE_RAMP_LEFT_BRACE_RAISED
                    || tile_id == SUBLOC_TILE_RAMP_LEFT_BRACKET)
                    family = 5;
                if (tile_id == SUBLOC_TILE_RAMP_GREATER
                    || tile_id == SUBLOC_TILE_RAMP_GREATER_RAISED
                    || tile_id == SUBLOC_TILE_RAMP_LEFT_BRACE_BACKPATCH
                    || tile_id == SUBLOC_TILE_RAMP_GREATER_BACKPATCH
                    || tile_id == SUBLOC_TILE_RAMP_RIGHT_BRACE_BACKPATCH
                    || tile_id == SUBLOC_TILE_RAMP_LESS)
                    family = 6;
                if (tile_id == SUBLOC_TILE_RAMP_RIGHT_BRACE
                    || tile_id == SUBLOC_TILE_RAMP_RIGHT_BRACE_RAISED
                    || tile_id == SUBLOC_TILE_RAMP_RIGHT_BRACKET)
                    family = 7;

                if ((row_record->flags & SUBROW_FLAG_SUPPRESS_TRACK_RENDER) != 0
                    || open_edge_mask == 0
                    || tile_id == SUBLOC_TILE_FLOOR_HASH_MARKER
                    || (g_runtime_config.render_flags & RUNTIME_RENDER_TRACK_FRINGE) == 0) {
                    cell->fringe_front = 0;
                    cell->fringe_right = 0;
                    cell->fringe_left = 0;
                    cell->fringe_back = 0;
                } else if (TestLoc(cell, 0, 0) == 1) {
                    if (!TestLoc(cell, 0, 1)) {
                        if (TestLoc(cell, 1, 1) != 1)
                            edge_a = (TestLoc(cell, 1, 0) != 1) + 1;
                        int edge_b;
                        if (TestLoc(cell, -1, 1) == 1)
                            edge_b = 0;
                        else
                            edge_b = (TestLoc(cell, -1, 0) != 1) + 1;

                        // The cell slot is a transient borrowed handle. The
                        // render-cache pass consumes and clears it after this
                        // builder completes.
                        emit_track_fringe(cell, &cell->fringe_front,
                            TRACK_FRINGE_FRONT, family, edge_a, edge_b);
                    } else {
                        cell->fringe_front = 0;
                    }

                    if (!TestLoc(cell, 1, 0)) {
                        if (TestLoc(cell, 1, -1) != 1)
                            edge_a = (TestLoc(cell, 0, -1) != 1) + 1;
                        int edge_b;
                        if (TestLoc(cell, 1, 1) == 1)
                            edge_b = 0;
                        else
                            edge_b = (TestLoc(cell, 0, 1) != 1) + 1;

                        emit_track_fringe(cell, &cell->fringe_right,
                            TRACK_FRINGE_RIGHT, family, edge_a, edge_b);
                    } else {
                        cell->fringe_right = 0;
                    }

                    if (!TestLoc(cell, -1, 0)) {
                        if (TestLoc(cell, -1, 1) != 1)
                            edge_a = (TestLoc(cell, 0, 1) != 1) + 1;
                        int edge_b;
                        if (TestLoc(cell, -1, -1) == 1)
                            edge_b = 0;
                        else
                            edge_b = (TestLoc(cell, 0, -1) != 1) + 1;

                        emit_track_fringe(cell, &cell->fringe_left,
                            TRACK_FRINGE_LEFT, family, edge_a, edge_b);
                    } else {
                        cell->fringe_left = 0;
                    }

                    if (!TestLoc(cell, 0, -1)) {
                        if (TestLoc(cell, -1, -1) != 1)
                            edge_a = (TestLoc(cell, -1, 0) != 1) + 1;
                        int edge_b;
                        if (TestLoc(cell, 1, -1) == 1)
                            edge_b = 0;
                        else
                            edge_b = (TestLoc(cell, 1, 0) != 1) + 1;

                        emit_track_fringe(cell, &cell->fringe_back,
                            TRACK_FRINGE_BACK, family, edge_a, edge_b);
                    } else {
                        cell->fringe_back = 0;
                    }
                }

                row_record = row_record_head;
                if ((row_record_head->flags
                        & SUBROW_FLAG_SUPPRESS_TRACK_RENDER)
                    != 0) {
                    Fringe* object = cell->fringe_front;
                    if (object != 0)
                        object->list_flags &= ~BOD_FLAG_RENDER_ENABLED;
                    object = cell->fringe_back;
                    if (object != 0)
                        object->list_flags &= ~BOD_FLAG_RENDER_ENABLED;
                    object = cell->fringe_right;
                    if (object != 0)
                        object->list_flags &= ~BOD_FLAG_RENDER_ENABLED;
                    object = cell->fringe_left;
                    if (object != 0)
                        object->list_flags &= ~BOD_FLAG_RENDER_ENABLED;
                }

                ++cell;
                --lane_count;
            } while (lane_count);

            row_record = row_record_head + 1;
            ++row;
            row_record_head = row_record;
        } while (row < runtime_row_count);
    }

    debug_report_stub(
        g_used_fringe_bods_format,
        g_game->subgame.fringe_manager.count);
}

